(5502609, 793777, 107180, '<td valign="top">Beautiful blue and gold colors, and the symbolism of the broken ring and reflection is really poignant.</td>', 'Beautiful blue and gold colors, and the symbolism of the broken ring and reflection is really poignant.', '2009-05-27 17:08:57.000000', NULL, 1),
(5502749, 793612, 106109, '<td valign="top">I feel his pain.<br/> <br/>Edit: After careful consideration, I gave this photo my highest score. Good luck.</td>', 'I feel his pain. Edit: After careful consideration, I gave this photo my highest score. Good luck.', '2009-05-27 18:55:21.000000', NULL, 1),
(5502757, 793612, 102315, '<td valign="top">I know the feeling! Very sharp focus and good portrayal of frustration.</td>', 'I know the feeling! Very sharp focus and good portrayal of frustration.', '2009-05-27 19:05:54.000000', NULL, 1),
(5502760, 793954, 102315, '<td valign="top">Great idea but I don''t know if having your username in the image is gonna hurt or help you to those who noticed it? Good luck with that. I remember your thread about quitting. Good luck with that and it''s great that you got the opportunity to use it in a challenge. I''m not gonna vote on this one because I know it''s yours. Feel I''ll be biased.</td>', 'Great idea but I don''t know if having your username in the image is gonna hurt or help you to those who noticed it? Good luck with that. I remember your thread about quitting. Good luck with that and it''s great that you got the opportunity to use it in a challenge. I''m not gonna vote on this one because I know it''s yours. Feel I''ll be biased.', '2009-05-27 19:08:50.000000', NULL, 1),
(5502762, 793760, 102315, '<td valign="top">Very out of focus and the shadow that it casts on the ceiling is very distracting.</td>', 'Very out of focus and the shadow that it casts on the ceiling is very distracting.', '2009-05-27 19:09:23.000000', NULL, 1),
