(5502766, 793309, 102315, '<td valign="top">Great original idea. I like the motion capture and the sharpness.</td>', 'Great original idea. I like the motion capture and the sharpness.', '2009-05-27 19:10:49.000000', NULL, 1),
(5502769, 793011, 102315, '<td valign="top">Great idea but the blur ruins it. This shot could have been set up so much better IMO.</td>', 'Great idea but the blur ruins it. This shot could have been set up so much better IMO.', '2009-05-27 19:11:26.000000', NULL, 1),
(5502770, 793900, 102315, '<td valign="top">I love it. If the little girl is not really pouting about something then she is a really great actor. Great image.</td>', 'I love it. If the little girl is not really pouting about something then she is a really great actor. Great image.', '2009-05-27 19:12:48.000000', NULL, 1),
(5502772, 793539, 88247, '<td valign="top">Oooo you tell such fibs!!<br/>Why break a habit of a life time...<br/>I bet you don''t:-)</td>', 'Oooo you tell such fibs!!Why break a habit of a life time...I bet you don''t:-)', '2009-05-27 19:13:22.000000', NULL, 1),
