(5506778, 793563, 28882, '<td valign="top">looks like something illegal going on here.</td>', 'looks like something illegal going on here.', '2009-05-31 17:27:18.000000', NULL, 1),
(5506830, 793919, 83313, '<td valign="top">This made me think of the professor from "Gilligan''s Island" who can make a nuclear reactor with a paperclip and chewing gum, but can''t fix a hole in a boat.</td>', 'This made me think of the professor from "Gilligan''s Island" who can make a nuclear reactor with a paperclip and chewing gum, but can''t fix a hole in a boat.', '2009-05-31 18:00:41.000000', NULL, 1),
(5506835, 793903, 83313, '<td valign="top">I don''t know whether to consider this a shoehorn or not, but then this really is a challenge where the title is a larger part of how it fits.  She''s awfully pretty, though.</td>', 'I don''t know whether to consider this a shoehorn or not, but then this really is a challenge where the title is a larger part of how it fits.  She''s awfully pretty, though.', '2009-05-31 18:02:55.000000', NULL, 1),
(5506836, 793634, 83313, '<td valign="top">It''s hard to tell if these boats are sitting in the background on a dock, or if they are on the bridge in the foreground. Don''t know why they would be on the bridge, but it looks that way.</td>', 'It''s hard to tell if these boats are sitting in the background on a dock, or if they are on the bridge in the foreground. Don''t know why they would be on the bridge, but it looks that way.', '2009-05-31 18:04:20.000000', NULL, 1),
(5506838, 793669, 83313, '<td valign="top">Quitting while ahead, or is this after a few failed marriages? Smart woman. Guys never change. Problem is, we are proud of it.</td>', 'Quitting while ahead, or is this after a few failed marriages? Smart woman. Guys never change. Problem is, we are proud of it.', '2009-05-31 18:05:58.000000', NULL, 1),
(5506839, 792824, 83313, '<td valign="top">Looks like a awesome spot that was worth the hike.</td>', 'Looks like a awesome spot that was worth the hike.', '2009-05-31 18:06:42.000000', NULL, 1),
(5506843, 793619, 83313, '<td valign="top">Is he making any money at this gig? Wonderful action shot.</td>', 'Is he making any money at this gig? Wonderful action shot.', '2009-05-31 18:08:07.000000', NULL, 1),
(5506844, 793247, 83313, '<td valign="top">Yuk-Yuk! Nice play on words. Love it!</td>', 'Yuk-Yuk! Nice play on words. Love it!', '2009-05-31 18:08:56.000000', NULL, 1),
(5506850, 793729, 83313, '<td valign="top">Needs a cleaning, which suggests an alternate title that also fits the challenge: "Why they quit making light tan keyboards".</td>', 'Needs a cleaning, which suggests an alternate title that also fits the challenge: "Why they quit making light tan keyboards".', '2009-05-31 18:13:05.000000', NULL, 1),
(5506852, 793879, 83313, '<td valign="top">That''s an awfully polite resignation letter. The kind most people actually submit, rather than the kind they really want to.</td>', 'That''s an awfully polite resignation letter. The kind most people actually submit, rather than the kind they really want to.', '2009-05-31 18:14:03.000000', NULL, 1),
(5506854, 793662, 83313, '<td valign="top">Great shot, wrong challenge? Ouch.</td>', 'Great shot, wrong challenge? Ouch.', '2009-05-31 18:15:12.000000', NULL, 1),
