(5507049, 793951, 83313, '<td valign="top">Nice, though I think it needs a little more tweaking to bring some more detail out of the shadows.</td>', 'Nice, though I think it needs a little more tweaking to bring some more detail out of the shadows.', '2009-05-31 21:38:21.000000', NULL, 1),
(5507050, 793662, 81362, '<td valign="top">Very nice still life, obviously clicked into the "I quit" challenge in error. Voting high, as though entered in the other challenge.</td>', 'Very nice still life, obviously clicked into the "I quit" challenge in error. Voting high, as though entered in the other challenge.', '2009-05-31 21:38:43.000000', NULL, 1),
