(5509200, 793903, 42495, '<td valign="top">Very nice portrait, but without your title I''m not seeing the correlation to the challenge.</td>', 'Very nice portrait, but without your title I''m not seeing the correlation to the challenge.', '2009-06-01 23:15:43.000000', NULL, 1),
