(5509215, 793309, 85310, '<td valign="top">I''m not sure I''d pick up on the "I quit" theme without the caption. I''d also question whether the letterbox framing effect adds to the overall picture.</td>', 'I''m not sure I''d pick up on the "I quit" theme without the caption. I''d also question whether the letterbox framing effect adds to the overall picture.', '2009-06-01 23:20:46.000000', NULL, 1),
(5509218, 793746, 42495, '<td valign="top">Good timing to catch the rainbow, but I''m not seeing "I quit".</td>', 'Good timing to catch the rainbow, but I''m not seeing "I quit".', '2009-06-01 23:21:57.000000', NULL, 1),
(5509222, 792919, 85310, '<td valign="top">Focus seems a little off, lacks sharpness, and I find the blown out background distracting.</td>', 'Focus seems a little off, lacks sharpness, and I find the blown out background distracting.', '2009-06-01 23:22:10.000000', NULL, 1),
(5509223, 793184, 42495, '<td valign="top">Good shot, but doesn''t meet the challenge, IMO.</td>', 'Good shot, but doesn''t meet the challenge, IMO.', '2009-06-01 23:22:21.000000', NULL, 1),
(5509225, 793896, 42495, '<td valign="top">That''s quite the interesting thing you have there!  I don''t really see the connection to the theme without your title.</td>', 'That''s quite the interesting thing you have there!  I don''t really see the connection to the theme without your title.', '2009-06-01 23:23:03.000000', NULL, 1),
(5509228, 793876, 42495, '<td valign="top">This is certainly an interesting picture and makes me want to know what''s going on.  I don''t see the connection to the challenge theme.</td>', 'This is certainly an interesting picture and makes me want to know what''s going on.  I don''t see the connection to the challenge theme.', '2009-06-01 23:23:54.000000', NULL, 1),
