(5512405, 792487, 106576, '<td valign="top">Hi,<br/>I am still new and didn''t vote but if I had this seems to really get to the heart of this challenge....and it is so relative to all of us! Especially true when you try hard and just don''t get what you either think is pretty good or you work and work and it''s still now up to what you hoped for.<br/>Thanks for a GREAT IMAGE for this challenge.</td>', 'Hi,I am still new and didn''t vote but if I had this seems to really get to the heart of this challenge....and it is so relative to all of us! Especially true when you try hard and just don''t get what you either think is pretty good or you work and work and it''s still now up to what you hoped for.Thanks for a GREAT IMAGE for this challenge.', '2009-06-03 15:11:42.000000', NULL, 0),
(5512409, 793934, 43774, '<td valign="top">Since you asked in the forums, here''s my opinion.  It''s a bit too dark, I don''t like that she is out of focus. The items on the table are cluttered and not all in focus and we''re not really sure what we''re looking at. Is that her hand holding her knee? Took me a while to figure that out, didn''t know what the "blob" was (no disrespect intended). The title is confusing. Why was this the moment she knew she must quit? There''s nothing there that suggests that.</td>', 'Since you asked in the forums, here''s my opinion.  It''s a bit too dark, I don''t like that she is out of focus. The items on the table are cluttered and not all in focus and we''re not really sure what we''re looking at. Is that her hand holding her knee? Took me a while to figure that out, didn''t know what the "blob" was (no disrespect intended). The title is confusing. Why was this the moment she knew she must quit? There''s nothing there that suggests that.', '2009-06-03 15:13:42.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5512494, 793905, 106576, '<td valign="top">Hmmm,<br/>I thought you had been spying on me and shot this!...:)<br/>I have one of these books and feel I should do them and when I start I wonder why am I doing this???<br/>The photo itself, I like the fact that you have the answers to one there, the puzzle being in the paper with the POV and all makes it very neat to me!<br/>Agree with the lighting being nice from the side.<br/> <br/>Thanks for showing it to us.<br/> <br/>(now can I break my pencil too?? ..:) )<br/></td>', 'Hmmm,I thought you had been spying on me and shot this!...:)I have one of these books and feel I should do them and when I start I wonder why am I doing this???The photo itself, I like the fact that you have the answers to one there, the puzzle being in the paper with the POV and all makes it very neat to me!Agree with the lighting being nice from the side. Thanks for showing it to us. (now can I break my pencil too?? ..:) )', '2009-06-03 15:52:13.000000', NULL, 0),
